const sharedSecret = 'GANTI_DENGAN_HASIL_OPENSSL_RAND_HEX_32';
const incoming = $input.first()?.json ?? {};
const headers = incoming.headers ?? {};
const suppliedSecret = String(headers['x-geopresensi-secret'] ?? headers['X-GeoPresensi-Secret'] ?? '');

if (sharedSecret === 'GANTI_DENGAN_HASIL_OPENSSL_RAND_HEX_32' || sharedSecret.length < 32) {
  throw new Error('Atur sharedSecret pada node ini sebelum mengaktifkan workflow.');
}
if (suppliedSecret !== sharedSecret) {
  throw new Error('Secret webhook GeoPresensi tidak cocok.');
}

const payload = incoming.body ?? incoming;
const chatIds = payload.chat_ids;
const message = String(payload.message ?? '').trim();
const keyboard = payload.reply_markup?.inline_keyboard;
const decisionButtons = Array.isArray(keyboard) ? (keyboard.find((row) => Array.isArray(row) && row.length >= 2) ?? []) : [];

if (!Array.isArray(chatIds) || chatIds.length === 0) {
  throw new Error('Payload harus berisi daftar chat_ids.');
}
if (!message || message.length > 4096) {
  throw new Error('Pesan Telegram kosong atau melebihi 4096 karakter.');
}
if (decisionButtons.length < 2 || !decisionButtons[0]?.callback_data || !decisionButtons[1]?.callback_data) {
  throw new Error('Tombol Setujui/Tolak tidak tersedia. Periksa konfigurasi webhook Telegram backend.');
}

return chatIds.map((chatId) => {
  const normalizedChatId = String(chatId).trim();
  if (!/^-?\d+$/.test(normalizedChatId)) {
    throw new Error('chat_id harus berupa ID Telegram numerik.');
  }
  return {
    json: {
      chatId: normalizedChatId,
      message,
      approveText: String(decisionButtons[0].text ?? '✅ Setujui'),
      approveCallbackData: String(decisionButtons[0].callback_data),
      rejectText: String(decisionButtons[1].text ?? '❌ Tolak'),
      rejectCallbackData: String(decisionButtons[1].callback_data)
    }
  };
});
